#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn int_enums_round_trip_their_python_values() {
        for z in Zone::ALL {
            assert_eq!(Zone::from_value(i64::from(z.value())), Some(z));
        }
        assert_eq!(Zone::ALL.len(), 12);
        for z in Phase::ALL {
            assert_eq!(Phase::from_value(i64::from(z.value())), Some(z));
        }
        assert_eq!(Phase::ALL.len(), 7);
        for z in Step::ALL {
            assert_eq!(Step::from_value(i64::from(z.value())), Some(z));
        }
        assert_eq!(Step::ALL.len(), 32);
        assert_eq!(Zone::ALL.len(), N_ZONES);
    }

    #[test]
    fn str_enums_round_trip_their_value_strings() {
        for k in DecisionKind::ALL {
            assert_eq!(DecisionKind::from_value(k.as_str()), Some(k));
        }
        assert!(
            DecisionKind::SORTED_BY_VALUE
                .windows(2)
                .all(|w| w[0].as_str() < w[1].as_str())
        );
        for k in ActionKind::ALL {
            assert_eq!(ActionKind::from_value(k.as_str()), Some(k));
        }
        assert!(
            ActionKind::SORTED_BY_VALUE
                .windows(2)
                .all(|w| w[0].as_str() < w[1].as_str())
        );
        for k in EndReason::ALL {
            assert_eq!(EndReason::from_value(k.as_str()), Some(k));
        }
        assert!(
            EndReason::SORTED_BY_VALUE
                .windows(2)
                .all(|w| w[0].as_str() < w[1].as_str())
        );
        for k in HistKind::ALL {
            assert_eq!(HistKind::from_value(k.as_str()), Some(k));
        }
        assert!(
            HistKind::ALL
                .windows(2)
                .all(|w| w[0] < w[1] && w[0].as_str() < w[1].as_str())
        );
        assert_eq!(HistKind::ALL.len(), 24);
        for k in EvKey::ALL {
            assert_eq!(EvKey::from_value(k.as_str()), Some(k));
        }
        assert!(
            EvKey::ALL
                .windows(2)
                .all(|w| w[0] < w[1] && w[0].as_str() < w[1].as_str())
        );
        assert_eq!(EvKey::ALL.len(), 20);
        for k in FrameKind::ALL {
            assert_eq!(FrameKind::from_value(k.as_str()), Some(k));
        }
        assert!(
            FrameKind::ALL
                .windows(2)
                .all(|w| w[0] < w[1] && w[0].as_str() < w[1].as_str())
        );
        assert_eq!(FrameKind::ALL.len(), 7);
        for k in EnginePrompt::ALL {
            assert_eq!(EnginePrompt::from_value(k.as_str()), Some(k));
        }
        assert!(
            EnginePrompt::ALL
                .windows(2)
                .all(|w| w[0] < w[1] && w[0].as_str() < w[1].as_str())
        );
        assert_eq!(EnginePrompt::ALL.len(), 14);
        for k in CtxKey::ALL {
            assert_eq!(CtxKey::from_value(k.as_str()), Some(k));
        }
        assert!(
            CtxKey::ALL
                .windows(2)
                .all(|w| w[0] < w[1] && w[0].as_str() < w[1].as_str())
        );
        assert_eq!(CtxKey::ALL.len(), 10);
    }
}
